import{_ as i,c as e,a,o as t}from"./app-5valQcRL.js";const n={};function s(o,l){return t(),e("div",null,[...l[0]||(l[0]=[a('<h1 id="skills-rules" tabindex="-1"><a class="header-anchor" href="#skills-rules"><span>Skills Rules</span></a></h1><h2 id="_1-配图规范" tabindex="-1"><a class="header-anchor" href="#_1-配图规范"><span>1. 配图规范</span></a></h2><p>在画图时，请检查图片布局的合理性：</p><ul><li>文字和图片等内容都不要有重叠</li><li>一行一列都要对齐，保持方正</li><li>使用统一的格子大小和坐标系</li><li>title 在各自的范围内居中排布</li><li>底部文字和上面内容的距离要合理，不要留太多空白</li></ul><h2 id="_2-图片宽度规范" tabindex="-1"><a class="header-anchor" href="#_2-图片宽度规范"><span>2. 图片宽度规范</span></a></h2><p>在文章中引用图片时：</p><ul><li>如果图的高度与宽度的比值 &gt; 0.5（即图比较&quot;高&quot;），使用 <code>=560x</code></li><li>如果图的高度与宽度的比值 ≤ 0.5（即图比较&quot;扁&quot;），不加宽度约束</li></ul><h2 id="_3-写作规范" tabindex="-1"><a class="header-anchor" href="#_3-写作规范"><span>3. 写作规范</span></a></h2><p>写内容时，要像给初中生讲故事一样，要有叙事性，但要遵循两个原则：</p><p><strong>原则一：简洁</strong></p><ul><li>提纲挈领，不能啰嗦</li><li>举一个例子就能理解的，就不要举好几个例子</li><li>能用一句话说清楚的，就不要用两句话</li></ul><p><strong>原则二：正确</strong></p><ul><li>必须要确保写的内容是对的</li><li>不确定的内容要给用户反馈，而不是瞎写</li><li>引用论文或数据时，要标注来源</li></ul><p><strong>叙事性要求：</strong></p><ul><li>用讲故事的方式引入概念，让读者理解&quot;为什么需要这个&quot;</li><li>比喻要恰当，但不要把比喻直接写进正文（比如&quot;SiLU是一把锄头&quot;）</li><li>比喻是用来帮助理解的，不是用来定义概念的</li></ul><h2 id="_4-文章结构规范" tabindex="-1"><a class="header-anchor" href="#_4-文章结构规范"><span>4. 文章结构规范</span></a></h2><p>组织文章时：</p><ul><li>不要把所有内容平铺成连续的二级标题，优先使用 <code>##</code> + <code>###</code> 的层级结构</li><li><code>##</code> 用来承载一个大问题，<code>###</code> 用来拆解这个问题下的几个小点</li><li>扩展内容不要插在正文主线中间，避免打断阅读；更适合放在小节末尾或总结部分</li><li>不要在正文里写编辑口吻的话，比如&quot;这部分更适合放在总结里&quot;，正文要直接面向读者</li></ul><h2 id="_5-算法类文章规范" tabindex="-1"><a class="header-anchor" href="#_5-算法类文章规范"><span>5. 算法类文章规范</span></a></h2><p>写&quot;算法&quot;相关内容时，先抽象任务定义，再讲流程：</p><ul><li>先说明：输入是什么，输出是什么，目标是什么</li><li>再说明：训练阶段怎么循环，预测阶段怎么输出</li><li>要区分&quot;任务定义&quot;、&quot;算法流程&quot;和&quot;网络结构&quot;，不要把三者混在一起</li><li>对于稳定任务，要突出哪些组件长期固定，哪些组件是主要变量</li><li>例如图像分类中，Softmax、CrossEntropy、训练闭环相对稳定，网络结构通常是主要变化点</li></ul><h2 id="_6-表达形式规范" tabindex="-1"><a class="header-anchor" href="#_6-表达形式规范"><span>6. 表达形式规范</span></a></h2><p>选择表格或列表时：</p><ul><li>横向字段多、需要对齐比较时，用表格</li><li>只有少量短句对照时，用 <code>-</code> 列表，不要强行做表格</li><li>如果一个表格横轴内容很少、读起来比列表更重，优先改成列表</li><li>长代码块不要连续堆在正文里，优先用 <code>code-group</code> / 标签页分组</li><li>PyTorch 和 NumPy 两种实现同时出现时，优先放进同一个代码组，避免阅读被长代码打断</li></ul><h2 id="_7-配图生成规范" tabindex="-1"><a class="header-anchor" href="#_7-配图生成规范"><span>7. 配图生成规范</span></a></h2><p>生成配图时：</p><ul><li>优先在 <code>scripts/image_gen</code> 下写可复现脚本，再输出到 <code>.vuepress/public/DeepLearning/...</code></li><li>图中如果某段时间或区域没有信息，可以用省略号压缩空白，不要让大量空白挤压主要内容</li><li>一维概念要画成线段，二维概念画平面，三维概念画空间；不要为了排版把低维概念画高维</li><li>训练流程图要画出闭环：参数更新后回到模型继续下一批/下一轮；预测输出要和训练循环区分开</li><li>指标类配图要一张图服务一个公式或一个概念，不要把多个指标强行合在一张图里</li></ul><h2 id="_8-指标类文章规范" tabindex="-1"><a class="header-anchor" href="#_8-指标类文章规范"><span>8. 指标类文章规范</span></a></h2><p>写评价指标时：</p><ul><li>小类别文章讲什么就只讲什么，先从当前指标的定义、公式和原理开始</li><li>不要在指标文章开头展开过多任务背景，也不要把主题扩成横向综述</li><li>推荐结构是：数学公式与原理解释、PyTorch / NumPy 中怎么使用、手写实现</li><li>公式和配图要互相对应，读者看公式再看图，就能理解这个指标怎么算</li></ul><h2 id="_9-协作规范" tabindex="-1"><a class="header-anchor" href="#_9-协作规范"><span>9. 协作规范</span></a></h2><p>和用户讨论时：</p><ul><li>如果用户明确说&quot;只是讨论，不要写&quot;，不要直接改文件</li><li>如果用户要求先给框架，就先给框架，不要直接写正文</li><li>当用户确认要写第一版时，再开始落地到文章和配图</li><li>修改已有文章时，优先局部更新，不要为了大改内容删除再重建同一路径文件</li><li>除非用户要求重命名或重建文件，否则保持文件历史和 diff 清晰</li></ul>',33)])])}const d=i(n,[["render",s]]),c=JSON.parse('{"path":"/AGENTS.html","title":"Skills Rules","lang":"en-US","frontmatter":{},"headers":[{"level":2,"title":"1. 配图规范","slug":"_1-配图规范","link":"#_1-配图规范","children":[]},{"level":2,"title":"2. 图片宽度规范","slug":"_2-图片宽度规范","link":"#_2-图片宽度规范","children":[]},{"level":2,"title":"3. 写作规范","slug":"_3-写作规范","link":"#_3-写作规范","children":[]},{"level":2,"title":"4. 文章结构规范","slug":"_4-文章结构规范","link":"#_4-文章结构规范","children":[]},{"level":2,"title":"5. 算法类文章规范","slug":"_5-算法类文章规范","link":"#_5-算法类文章规范","children":[]},{"level":2,"title":"6. 表达形式规范","slug":"_6-表达形式规范","link":"#_6-表达形式规范","children":[]},{"level":2,"title":"7. 配图生成规范","slug":"_7-配图生成规范","link":"#_7-配图生成规范","children":[]},{"level":2,"title":"8. 指标类文章规范","slug":"_8-指标类文章规范","link":"#_8-指标类文章规范","children":[]},{"level":2,"title":"9. 协作规范","slug":"_9-协作规范","link":"#_9-协作规范","children":[]}],"git":{"createdTime":null,"updatedTime":null,"contributors":[]},"filePathRelative":"AGENTS.md"}');export{d as comp,c as data};
